+static const size_t INSERTION_SORT_THRESHOLD = 64;
+static const int RADIX_PASSES = 4;
+static const uint32_t RADIX_MASK = 0xFF;
+
+static void insertion_sort(uint32_t* a, size_t n) {
+    for (size_t i = 1; i < n; ++i) {
+        uint32_t v = a[i];
+        size_t j = i;
+        while (j && a[j - 1] > v) {
+            a[j] = a[j - 1];
+            j--;
+        }
+        a[j] = v;
