-    std::vector<uint32_t> tmp(n);
-    merge_sort_rec(a, tmp.data(), 0, n);
+    if (n < 2) return;
+    if (n < INSERTION_SORT_THRESHOLD) {
+        insertion_sort(a, n);
+        return;
+    }
