+    std::vector<uint32_t> scratch(n);
+    uint32_t* src = a;
+    uint32_t* dst = scratch.data();
+    size_t shift = 0;
+
+    for (int pass = 0; pass < RADIX_PASSES; ++pass) {
+        uint32_t count[256] = {0};
+        for (size_t i = 0; i < n; ++i) {
+            count[(src[i] >> shift) & RADIX_MASK]++;
+        }
+        uint32_t total = 0;
+        for (int i = 0; i < 256; ++i) {
+            uint32_t c = count[i];
+            count[i] = total;
+            total += c;
+        }
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t byte = (src[i] >> shift) & RADIX_MASK;
+            dst[count[byte]++] = src[i];
+        }
+        std::swap(src, dst);
+        shift += 8;
+    }
